const getTenantSupportRequestCounts = `-- name: GetTenantSupportRequestCounts :one
SELECT 
    COUNT(*) FILTER (WHERE assignee_id IS NULL) AS unassigned_count,
    COUNT(*) FILTER (
        WHERE assignee_id IS NOT NULL 
          AND assignee_id IS NOT DISTINCT FROM $1
    ) AS mine_count,
    COUNT(*) FILTER (
        WHERE assignee_id IS NOT NULL 
          AND assignee_id IS DISTINCT FROM $1
          AND status NOT IN ('completed', 'declined')
    ) AS team_count,
    COUNT(*) AS all_count
FROM requests
WHERE tenant_id = $2
  AND request_type = 'support'
`

type GetTenantSupportRequestCountsParams struct {
	EmployeeID *uuid.UUID `json:"employeeId"`
	TenantID   uuid.UUID  `json:"tenantId"`
}

type GetTenantSupportRequestCountsRow struct {
	UnassignedCount int64 `json:"unassignedCount"`
	MineCount       int64 `json:"mineCount"`
	TeamCount       int64 `json:"teamCount"`
	AllCount        int64 `json:"allCount"`
}

func (q *Queries) GetTenantSupportRequestCounts(ctx context.Context, arg GetTenantSupportRequestCountsParams) (GetTenantSupportRequestCountsRow, error) {
	row := q.db.QueryRow(ctx, getTenantSupportRequestCounts, arg.EmployeeID, arg.TenantID)
	var i GetTenantSupportRequestCountsRow
	err := row.Scan(
		&i.UnassignedCount,
		&i.MineCount,
		&i.TeamCount,
		&i.AllCount,
	)
	return i, err
}

